// CSV ↔ JSON Converter

var mode = input.get("mode") || "toJson";
var inputText = input.get("inputText");
var delimiter = input.get("delimiter") || ",";
var hasHeaders = input.get("hasHeaders") !== "false";

if (!inputText || inputText.trim() === "") {
    log.error("Input is required");
    output.set("HasErrors", true);
    output.set("ErrorMessage", "Input is required");
    output.set("Result", "");
    tags.trigger("error");
} else {
    try {
        var result = "";

        if (mode.toLowerCase() === "tocsv" || mode.toLowerCase() === "encode") {
            // JSON array to CSV
            var data = json.parse(inputText);
            if (!Array.isArray(data) || data.length === 0) {
                throw new Error("Input must be a non-empty JSON array");
            }

            // Get headers from first object
            var headers = Object.keys(data[0]);
            var lines = [];

            if (hasHeaders) {
                lines.push(headers.join(delimiter));
            }

            for (var i = 0; i < data.length; i++) {
                var row = [];
                for (var j = 0; j < headers.length; j++) {
                    var val = data[i][headers[j]];
                    if (val === null || val === undefined) val = "";
                    val = String(val);
                    // Escape quotes and wrap if contains delimiter or quotes
                    if (val.indexOf(delimiter) >= 0 || val.indexOf('"') >= 0 || val.indexOf('\n') >= 0) {
                        val = '"' + val.replace(/"/g, '""') + '"';
                    }
                    row.push(val);
                }
                lines.push(row.join(delimiter));
            }
            result = lines.join('\n');
            output.set("RowCount", data.length);
            output.set("ColumnCount", headers.length);
            log.info("Converted JSON to CSV: " + data.length + " rows, " + headers.length + " columns");
        } else {
            // CSV to JSON array
            var lines = inputText.trim().split('\n');
            if (lines.length === 0) {
                throw new Error("CSV input is empty");
            }

            // Parse CSV line handling quoted values
            function parseLine(line) {
                var result = [];
                var current = "";
                var inQuotes = false;
                for (var i = 0; i < line.length; i++) {
                    var c = line[i];
                    if (c === '"') {
                        if (inQuotes && i + 1 < line.length && line[i + 1] === '"') {
                            current += '"';
                            i++;
                        } else {
                            inQuotes = !inQuotes;
                        }
                    } else if (c === delimiter && !inQuotes) {
                        result.push(current);
                        current = "";
                    } else {
                        current += c;
                    }
                }
                result.push(current);
                return result;
            }

            var headers = parseLine(lines[0]);
            var startRow = hasHeaders ? 1 : 0;

            if (!hasHeaders) {
                headers = [];
                for (var h = 0; h < parseLine(lines[0]).length; h++) {
                    headers.push("col" + h);
                }
            }

            var data = [];
            for (var i = startRow; i < lines.length; i++) {
                if (lines[i].trim() === "") continue;
                var values = parseLine(lines[i]);
                var obj = {};
                for (var j = 0; j < headers.length; j++) {
                    obj[headers[j]] = values[j] || "";
                }
                data.push(obj);
            }

            result = json.stringify(data);
            output.set("RowCount", data.length);
            output.set("ColumnCount", headers.length);
            output.set("Headers", json.stringify(headers));
            log.info("Converted CSV to JSON: " + data.length + " rows, " + headers.length + " columns");
        }

        output.set("Result", result);
        output.set("Mode", mode);
        output.set("HasErrors", false);
        output.set("ErrorMessage", "");
        tags.trigger("success");

    } catch (ex) {
        log.error("Conversion failed: " + ex.message);
        output.set("HasErrors", true);
        output.set("ErrorMessage", ex.message);
        output.set("Result", "");
        tags.trigger("error");
    }
}
